      "大多數人平常就在做報酬函數工程，只是對象是人：父母教孩子價值觀、師父教新手操作、經理人給部屬目標。對人做的時候，預測和判斷是綜合在一起的，所以這個角色不明顯；機器預測愈好，它就愈重要。求職平台[[ZipRecruiter]]以媒合演算法大規模幫企業找到合格人選，但不確定該收多少錢：收太少會錯過獲利，收太多顧客會流向對手。",
