      "韓默與錢辟最愛的例子是福特（Ford）在 1980 年代的困境。福特北美的會計（應付帳款, accounts payable）部門雇用 500 人，原本希望靠大筆電腦投資把人數減少 20%，降到約 400 人——看來並不離譜，直到對照競爭對手馬自達（Mazda）：同樣的部門只有 **5 個人**。",
