      "哈佛商學院教授、經濟學家兼律師[[班·艾德曼|Ben Edelman]]向作者解釋，這個問題為何對雇主與臉書都可能很嚴重。許多人以為歧視來自[[差別待遇|disparate treatment]]，也就是對男性與女性設定不同標準；但廣告版位的差別會造成律師所說的[[差別性影響|disparate impact]]——一個性別中立的程序，最後讓有理由擔心受歧視的[[受保護類別|protected class]]員工處於不同的處境。",
      "就算是意外，也有人或組織要負責。法院曾認定**紐約市消防局** (FDNY) 歧視黑人與西班牙裔申請者：消防員考試加入幾道強調閱讀理解、與職務無關的試題，而這兩個族群在這些題目上表現往往較差。此案最後以約 **9,900 萬美元**和解——歧視並非故意，消防局仍須負責。",
      "因此，即使你以為自己只是在臉書投放中性的廣告，身為雇主仍可能因差別性影響而承擔責任。臉書的一個解決辦法，是提供廣告主避免歧視的工具。"
