      "策略考量是：如果競爭對手能觀察你 AI 的**輸入**（如搜尋問題）與**輸出**（如網站列表），就有原料用自己的 AI 進行[[監督式學習|supervised learning]]、重建你的演算法。要以此徵用 Google 搜尋引擎非常困難，但原則上相當可能。2016 年資訊工程學者證明，某些深度學習演算法尤其無法防範這種模仿：在亞馬遜機器學習 (Amazon Machine Learning) 等重要平台上，只需相對少量（**650 至 4,000 次**）查詢，就能把模型逆向工程到非常近似、有時甚至完美。",
